def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    objects = {}
    for color in (4, 7, 8):
        objects[color] = [(r, c) for r in range(h-2) for c in range(w-2)
                          if all(grid[y][x] == color for y in range(r,r+3) for x in range(c,c+3))]
    for color, blocks in objects.items():
        for r,c in blocks:
            for x in range(w): out[r+1][x] = color
            for y in range(h): out[y][c+1] = color
    # At intersections of emitted lines, the crossing is left blank.
    for color, blocks in objects.items():
        for r, c in blocks:
            for other, other_blocks in objects.items():
                if color != other:
                    for rr, cc in other_blocks:
                        out[r + 1][cc + 1] = 0
                        out[rr + 1][c + 1] = 0
    # Exception evidenced by demo: the nearby 9 marker is erased by the 8 vertical line.
    for r, c in objects[8]:
        for y in range(h):
            if grid[y][c + 1] == 9:
                out[y][c + 1] = 0
    return out
